primaryQuery:
run: order_items -> {
  aggregate:
    item_return_rate is count() { where: status = 'Returned' } / nullif(count(), 0)
}

verifyQuery:
run: order_items -> {
  group_by: status
  aggregate: n is count()
} -> {
  aggregate:
    returned is n.sum() { where: status = 'Returned' }
    total is n.sum()
} -> {
  select: item_return_rate is returned / total
}
